const teamIdOf = (body: unknown): string => (body as { readonly team: { readonly id: string } }).team.id;

interface Detail {
  readonly id: string;
  readonly questions: ReadonlyArray<{
    readonly questionId: string;
    readonly templateKey: string | null;
    readonly text: string;
  }>;
