/**
 * A test send as the Durable Object found it: whose it is, which Pulse it tests, when it was queued,
 * and the state its email is in. `null` for a send that has no test row.
 */
export interface TestSendFound {
  readonly personId: PersonId;
  readonly pulseId: PulseId;
  readonly sentAt: number;
  readonly state: SendState;
}

/** A send's state as the editor shows it (ADR 0006). A send with no state yet is queued with no attempts. */
export const testSendStatusOf = (state: SendState, queuedAt: number, checkedAt: number): TestSendStatus => {
  switch (state._tag) {
    case "Pending":
      return { queuedAt, checkedAt, state: { _tag: "Queued", attempts: state.attempts, lastCode: state.lastCode } };
    case "Sending":
      return { queuedAt, checkedAt, state: { _tag: "Sending", attempt: state.attempt } };
    case "Sent":
      return { queuedAt, checkedAt, state: { _tag: "Sent", sentAt: state.sentAt } };
    case "Failed":
      return {
        queuedAt,
        checkedAt,
        state: { _tag: "Failed", reason: state.reason, code: state.code, failedAt: state.failedAt },
      };
  }
};

/**
 * The state of the sender's own test send, for the Pulse editor to poll (ADR 0021). Only the Person
 * who sent it may see it, and only for the Pulse it tests, within the test's lifetime. Everything else
 * is "not found", so a send id reveals nothing about another Person's send.
 */
export const testSendView = (
  directory: DirectoryState,
  actorId: PersonId,
  teamId: TeamId,
  pulseId: PulseId,
  found: TestSendFound | null,
  now: number,
): PulseViewed<TestSendStatus> =>
  viewAuthorized(directory, actorId, teamId, () => {
    if (
      found === null ||
      found.personId !== actorId ||
      found.pulseId !== pulseId ||
      found.sentAt <= now - testInvitationLifetimeMs
    ) {
      return reject({ _tag: "TestSendNotFound" });
    }
    return { _tag: "Viewed", value: testSendStatusOf(found.state, found.sentAt, now) };
  });
'''
