/** The state the sender reads back for one test send: the editor's poll (ADR 0021). */
describe("reading a test send's state (issue 147)", () => {
  const testPath = (teamId: string, pulseId: string) =>
    `/api/teams/${teamId}/pulses/${pulseId}/test-invitation`;
  const statePath = (teamId: string, pulseId: string, sendId: string) =>
    `/api/teams/${teamId}/pulses/${pulseId}/test-invitations/${sendId}`;

  /** Sets a test send's email state by hand: the fake never delivers. */
  const setState = (world: SignInWorld, sendId: string, state: unknown) => {
    for (const organization of world.durable.organizations.values()) {
      const send = organization.sends.get(sendId as never);
      if (send !== undefined) organization.sends.set(sendId as never, { ...send, state: state as never });
    }
  };

  it("is Queued from the send until the queue settles it, and carries no message, token, or address", async () => {
    const { world, lead, teamId } = await setup();
    const pulse = await createPulse(lead, teamId);
    const sent = await lead.call("POST", testPath(teamId, pulse.id));
    const sendId = (sent.body as { readonly sendId: string }).sendId;
    const status = await lead.call("GET", statePath(teamId, pulse.id, sendId));
    expect(status).toMatchObject({
      status: 200,
      body: {
        queuedAt: expect.any(Number),
        checkedAt: expect.any(Number),
        state: { _tag: "Queued", attempts: 0, lastCode: null },
      },
    });
    expect(Object.keys(status.body as object).sort()).toEqual(["checkedAt", "queuedAt", "state"]);

    setState(world, sendId, { _tag: "Failed", reason: "rejected", code: "E_SENDER_NOT_VERIFIED", failedAt: 9 });
    expect(await lead.call("GET", statePath(teamId, pulse.id, sendId))).toMatchObject({
      status: 200,
      body: { state: { _tag: "Failed", reason: "rejected", code: "E_SENDER_NOT_VERIFIED", failedAt: 9 } },
    });
  });

  it("answers the other states the queue can be in", async () => {
    const { world, lead, teamId } = await setup();
    const pulse = await createPulse(lead, teamId);
    const sendId = (await lead.call("POST", testPath(teamId, pulse.id))).body as { sendId: string };
    const path = statePath(teamId, pulse.id, sendId.sendId);
    setState(world, sendId.sendId, { _tag: "Sending", attempt: 2, leaseExpiresAt: 99 });
    expect((await lead.call("GET", path)).body).toMatchObject({ state: { _tag: "Sending", attempt: 2 } });
    setState(world, sendId.sendId, { _tag: "Sent", messageId: "provider-7", sentAt: 4 });
    const sent = await lead.call("GET", path);
    expect(sent.body).toMatchObject({ state: { _tag: "Sent", sentAt: 4 } });
    expect(JSON.stringify(sent.body)).not.toContain("provider-7");
